from functools import reduce
from fractions import Fraction
from math import gcd

def factorial(n):
    return reduce(lambda x, y: x*y % 1000000007, range(1, n+1))

def modular_inverse(n):
    return pow(n, -1, 1000000007)

def beauty_sequence_factorial(n, k):
    return (n-1)**n * k**n % 1000000007

def trial_division(n):
    factors = []
    d = 2
    while d*d <= n:
        if n % d == 0:
            factors.append(d)
            n //= d
        else:
            d += 1
    if n > 1:
        factors.append(n)
    return factors

def find_p_and_q(n, k):
    a = k**n * beauty_sequence_factorial(n, k) % 1000000007
    b = 0
    for _ in range(n-1):
        c = factorial(a) * modular_inverse(a) % 1000000007
        b += gcd(b, c)
        a -= n
        a //= c
    result = b // factorial(b)
    return result % 1000000007

# Read integers n and k from input
n, k = map(int, input().split())

# Calculate the expected value of f(s)^2 of a uniformly chosen at random word
