from math import gcd
from typing import List

def find_strange_set(a: List[int], b: List[int]) -> int:
    mod = 10**9 + 7
    dp = [[0] * (a[-1] + 1) for _ in range(len(a))]  # dp[i][j] is the max cost of a str. set ending at j in the first half

    # Calculate gcds and apply the rule
    for i in range(len(a)):
        for j in range(min(i, a[i]), a[i] + 1):
            found = False
            for k in range(j * gcd(a[i], j), j + 1):
                if a[i] % k == 0:
                    dp[i][k] = max(dp[i][k], dp[i-1][j] + b[i])
                    found = True
                    break  # We don't need to check further for the current i < j
            if not found:
                dp[i][j] = b[i]  # Empty set is strange by definition

    # Now, for the second half, we fold
    ans = 0
    for i in range(len(a)):
        for j in range(i, a[i] + 1):
            if dp[i][j] > 0:
                ans = max(ans, dp[i][j] + b[i + len(a) - j])

    return ans % mod

# Example test cases
print(find_strange_set([4, 7, 3, 4, 5, 6, 7, 8, 13], [-2, 3, -19, 5, -6, 7, -8, 9, 1]))  # Expected output: 16
print(find_strange_set([42, 42], [-37, 13]))  # Expected output: 0
print(find_strange_set([42, 42], [13, -37]))  # Expected output: 13
