Here is the Python program to solve the problem:

```python
from collections import defaultdict
import heapq

def play_game(piles):
    n = len(piles)
    segment = [piles[i] for i in range(n)]  # Initial piles form a single segment

    # Remove segments with length 1
    while True:
        try:
            i, j = heapq.heappop(segment)
        except:
            break
        segment.pop(j)
        if (j - i + 1) <= 1:
            segment.extend(segment[j:])

    return segment

def count_in_segment(segment, p, length):
    seg_start, seg_end = -float("inf"), -float("inf")
    while True:
        try:
            i, j = heapq.heappop(segment)
        except:
            break
        if max((i - seg_start, seg_end - j + 1)) < length:
            heapq.heappush(segment, (i, j))
            heapq.heappush(segment, (seg_end + 2, seg_end))
            if max((i - seg_start, seg_end - j + 1)) >= length:
                seg_start = j
                seg_end = i
                count[0] += 2
                break
    return sum(segment[j:i + 1] for i, j in segment)

def solution(A):
    max_count = 0
    main_heap = []

    cum_piles = defaultdict(set)
    for i, a in enumerate(A):
        for j in range(a):
            cum_piles[j].add(i + 1)

    for size, pile_set in cum_piles.items():
        for sp in pile_set:
            heapq.heappush(main_heap, sp)
        segment = play_game(cum_piles[size])
        for i, count in enumerate(segment):
            for j, p in enumerate(segment[i:], i):
                max_count += count_in_segment(segment, p, size - count + i)
    return max_count
