def is_route_possible(N, D, temperatures):
    # Initialize the list of visited cities
    visited = [False] * N

    # Sort the temperatures in ascending order
    temperatures.sort()

    # Check if each city can be visited starting from city 1
    for i in range(N):
        if (temperatures[i] - temperatures[0]) <= D:
            visited[i] = True
        else:
            break

    # Restore the visited cities to their original order
    for i in range(N):
        if not visited[i]:
            temperatures.sort()  # Resort the temperatures to simulate travel back to the city
            index = 0
            for city in range(1, N):
                if temperatures[city] - temperatures[index] <= D:
                    del temperatures[city]
                else:
                    index += 1
            break  # found a way and it cannot return to city 1, leave the loop

    # Check if the number of cities visited is equal to N
    return len(temperatures) == 1

