from collections import defaultdict

def group_piles(piles):
    # Group piles into contiguous segments based on pile size
    segments = defaultdict(list)
    for i, pile in enumerate(piles):
        if not segments[pile]:
            segments[pile].append(((i, pile),))
        else:
            segments[pile].append(((i, pile), (i, pile),))

    # For each segment, group segments by the maximum pile size
    for pile in segments:
        segments[pile] = sorted(segments[pile], key=lambda x: x[1])
        blocks = segments[pile]
        piles += [(pile, max(bs[1] for bs in blocks) - piles.index(bs[0][1]) -1) for bs in blocks]
    return piles

def game(A, piles):
    if len(piles) == 1:
        return A == 1
    elif A == 1:
        if 1 in piles[0][1:]:
            return game(piles[0][1:], game(piles[1:], piles[2:])) or game(piles[1][1:], game(piles[0:], piles[2:])) or game(piles[0], piles[1])
        return False
    else:
        first, rest = piles[0]
        count = 0
        for rest_i, rest_piles in rest:
            if rest_piles == first or (rest_i == first + count and rest[rest_i] == first - 1):
                count += 1

        if count == 1 and game(A - 1, piles[1:]):
            return True
        elif count - 1 == 1 and game(A - 1, reversed([max(s[1]) for s in piles[1:]])):
            return True
        return False

if __name__ == '__main__':
    N = int(input())
    piles = [list(map(int, input().split())) for _ in range(N)]

    games_won = 0
    for A in piles:
        divisions = group_piles(sorted(A, reverse=True))
        if game(len(divisions), divisions):
            games_won += 1

    print(games_won)
