                            (mHeap.top()[0] + (mHeap.top()[1] + nDigit) // m) % 10
                        ] else 0
                    break
                mHeap.remove()
        flag[digcount[-1][-1]] = True
        digcount.pop()
        dp.pop()
    while len(anss) < nMinus1:
        while (dpSorted := sorted(zip(dp, range(nMinus1 - 1, -1, -1)))).size() < 2:
            if dpSorted[-2][1] not in flag:
                break
            anss.append(flag[dpSorted[-2][1]])
    return anss
