class Graph:
    def __init__(self):
        self.edges = []
        self.graph = defaultdict(list)
        self.max_color = 2
        self.coloring = defaultdict(int)
        self.post_order = set()

    def add_edge(self, x, y):
        self.graph[x].append(y)
        self.edges.append((x, y, ri(1, self.max_color)))

    def calc_hash(self, coloring):
        return int(sum([2**color - coloring for x, y, color in self.edges]) % 998244353)

    def post_order_floyd(self):
        for i in range(self.max_color):
            for j in range(self.max_color):
                for k in range(self.max_color):
                    if (self.graph[i][j] and self.graph[j][k]) or (not self.graph[i][j] and not self.graph[j][k]):
                        self.graph[i][k] = self.graph[j][k]

    def process_hash(self, coloring):
        for i, j in self.graph:
            for x, y, z in self.edges:
                if z == 1 and self.coloring[x] == 1 and self.coloring[j] == 1:
                    self.graph[x].remove(i)
                    self.graph[j].remove(i)
                    break

class Solution:
    def __init__(self):
        self.graph = Graph()
        self.colors = set()
        self.results = []
        self.seen_first = -1
        self.seen_second = -1

    def process_I_query(self, q, x, y):
        self.graph.add_edge(q, x)
        self.graph.add_edge(q, y)
        self.seen_first, self.seen_second = x, y
        if (self.seen_first, self.seen_second) in self.graph:
            self.post_order_floyd()
        else:
            self.graph.add_edge(self.seen_first, self.seen_second)

        self.graph.post_order_floyd()
        if (self.seen_first, self.seen_second) in self.graph:
            self.graph.graph[self.seen_first].remove(self.seen_second)
        if (self.seen_second, self.seen_first) in self.graph:
            self.graph.graph[self.seen_second].remove(self.seen_first)

        self.colors = set()
        color_index = 1
        for i in range(self.graph.max_color):
            for j in self.graph.graph[i]:
                if not self.graph.coloring[i]:
                    self.graph.coloring[i] = color_index
                    color_index = (color_index + 1) % self.graph.max_color
                    for k in range(self.graph.max_color):
                        for l in range(self.graph.max_color):
                            if k and l and self.graph.graph[i][k] and self.graph.graph[k][l]:
                                self.graph.graph[i][j] = l
                                self.graph.graph[k][l] = j
                                break

        optimal_coloring = self.graph.calc_hash(self.graph.coloring)

        self.results.append(optimal_coloring)
        return optimal_coloring

    def process_F_query(self, q, x, y):
        nn = self.graph.graph[x].pop()
        self.graph.graph[y].discard(nn)
        s = set()
        for i in range(self.graph.max_color):
            if not self.graph.graph[i]:
