            if not self.graph.graph[i][nn]:
                continue
            if not self.graph.graph[i][nn]:
                continue
            s.add(self.graph.graph[i][nn])
        if self.graph.coloring[y] not in s:
            self.graph.coloring[y] = 1
        self.graph.graph[x].add(nn)
        self.graph.graph[nn].add(x)

        self.process_I_query(q, x, nn)
        return 

