from collections import defaultdict

def eular_path(graph):
    n = len(graph)
    cycle, stack, trace = [0] * n, [0] * n, [0] * n
    trace[0] = 1
    white = 0
    for u in range(n-1):
        if cycle[u] == 0:
            white += 1
            for v, w in graph[u]:
                cycle[v] = w
                if cycle[w] == 0:
                    stack = [w] + stack
                    trace[w] = 1
                    break
            else:
                stack = [-1] + stack
                white -= 1
            n += 1
            for i in range(n-1):
                if cycle[i] == 0:
