from math import gcd, powmod

def extended_gcd(x, y):
    """Extended Euclidean Algorithm to find the coefficients of Bezout's identity"""
    if y == 0:
        return x, 1, 0
    gcd, x1, y1 = extended_gcd(y, x % y)
    x, y = y1, x - (x // y) * y
    return gcd, x, y

def inverse_modulo(q, p):
    """Calculate the modular multiplicative inverse"""
    _, x, _ = extended_gcd(q, p)
    return powmod(x, p - 2, p)

def beauty_value(word, k):
    """Function to calculate beauty of a word"""
    prefix_sums = 0
    for i, char in enumerate(word):
        if char == word[i + 1]:
            prefix_sums += 1
    return prefix_sums

def beauty_squared_value(word, k, n):
    """Calculate expected value of f(s)^2 for given word"""
    counts = [0] * n  # count of consecutive matches with k prefixes
    word_counts = [0] * k  # count of s[i] appearing at i-th position

    for i in range(n):
        word_counts[word[i]] += 1
        if word[i] == word[0]:
            counts[i] = n - 1 - counts[i]
        else:
            counts[i] = n - 1 - counts[i - 1]

    expected_squared_beauty = 0
    for word_count in word_counts:
        for count in counts[word_count]:
            expected_squared_beauty += pow(count, 2) * pow(word_count, -1, k + 1)
    return powmod(expected_squared_beauty, n, k + 1) * powinv((k ** (n - 1) * (k + 1) // 2), n, k + 1)

def powmod(a, b, m):
    """Modular exponentiation"""
    ans = 1
    while b:
        if b & 1:
            ans = (ans * a) % m
        a = (a ** 2) % m
        b >>= 1
    return ans

def powinv(a, m):
    """Invert modulo m"""
    return powmod(a, m - 2, m)

